<?php $pageTitle='Productos'; require __DIR__.'/_header.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf($_POST['csrf']??null);$id=(int)$_POST['id'];$price=(float)$_POST['price'];$stock=$_POST['stock']===''?null:(int)$_POST['stock'];$active=isset($_POST['active'])?1:0;$q=db()->prepare('UPDATE products SET price=?,stock=?,active=? WHERE id=?');$q->execute([$price,$stock,$active,$id]);}$rows=db()->query('SELECT * FROM products ORDER BY sort_order,id')->fetchAll();?><div class="product-admin-grid"><?php foreach($rows as $p):?><form class="admin-card" method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=$p['id']?>"><img class="admin-product-img" src="../<?=h($p['image'])?>" alt=""><h2><?=h($p['name'])?></h2><label>Precio Bs<input type="number" step="0.01" name="price" value="<?=h((string)$p['price'])?>"></label><label>Stock<input type="number" name="stock" value="<?=h((string)$p['stock'])?>"></label><label class="check"><input type="checkbox" name="active" <?=$p['active']?'checked':''?>> Activo</label><button class="btn primary wide">Guardar</button></form><?php endforeach;?></div><?php require __DIR__.'/_footer.php';?>